void PlayNestedCalls(const char* import)
{
    NestedScope scope;
    for (int k = 0; k < scope.count; k++) {
        scope.Restore();
        const char* args = nullptr;
        const char* name = NestedName(scope.line[k], &args);
        CallbackUnknown(import, k, name);
    }
}

